import { APP_REGISTRY } from '@/app/config/appRegistry'
import { useTenant } from '@/app/providers/TenantProvider'

export function AppsAdminPage() {
  const { manifest } = useTenant() as any
  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-3xl mx-auto">
        <h2 className="font-semibold mb-1">Apps</h2>
        <p className="text-sm text-muted-foreground mb-6">Enable or disable apps for this tenant</p>
        <div className="bg-surface rounded-xl border border-border divide-y divide-border">
          {APP_REGISTRY.map((app) => {
            const enabled = manifest?.enabledApps?.includes(app.id) ?? false
            return (
              <div key={app.id} className="flex items-center gap-3 px-5 py-3">
                <div className="flex-1">
                  <p className="text-sm font-medium">{app.label}</p>
                  <p className="text-xs text-muted-foreground">{app.description}</p>
                </div>
                <span className="text-xs px-2 py-0.5 rounded-full bg-muted capitalize">{app.level}</span>
                <label className="inline-flex items-center cursor-pointer">
                  <input type="checkbox" defaultChecked={enabled} className="sr-only peer" />
                  <div className="w-9 h-5 bg-muted peer-checked:bg-accent rounded-full relative transition-colors after:content-[''] after:absolute after:top-0.5 after:left-0.5 after:bg-background after:rounded-full after:h-4 after:w-4 after:transition-transform peer-checked:after:translate-x-4" />
                </label>
              </div>
            )
          })}
        </div>
      </div>
    </div>
  )
}
